import java.util.*;

record Order(long id, String status) {}

interface OrderRepository {
    Optional<Order> findById(long id);
    void save(Order order);
}

class FakeOrderRepository implements OrderRepository {
    private final Map<Long, Order> orders = new LinkedHashMap<>();

    public Optional<Order> findById(long id) {
        return Optional.ofNullable(orders.get(id));
    }

    public void save(Order order) {
        orders.put(order.id(), order);
    }
}

class OrderService {
    private final OrderRepository repository;
    OrderService(OrderRepository repository) { this.repository = repository; }

    String cancel(long id) {
        Optional<Order> found = repository.findById(id);
        if (found.isEmpty()) return "NOT_FOUND";
        Order order = found.get();
        if (order.status().equals("PAID")) return "CONFLICT";
        if (order.status().equals("CANCELLED")) return "NO_CHANGE";
        repository.save(new Order(id, "CANCELLED"));
        return "CANCELLED";
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
