import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int stable = 0, flaky = 0;
        for (int i = 0; i < n; i++) {
            String name = sc.next();
            String clock = sc.next(), random = sc.next(), state = sc.next();
            String wait = sc.next(), network = sc.next();
            List<String> risks = new ArrayList<>();
            if (clock.equals("real")) risks.add("CLOCK");
            if (random.equals("unseeded")) risks.add("RANDOM");
            if (state.equals("shared")) risks.add("STATE");
            if (wait.equals("sleep")) risks.add("WAIT");
            if (network.equals("live")) risks.add("NETWORK");
            if (risks.isEmpty()) {
                stable++;
                System.out.println(name + " STABLE");
            } else {
                flaky++;
                System.out.println(name + " FLAKY " + String.join(",", risks));
            }
        }
        System.out.println("SUMMARY stable=" + stable + " flaky=" + flaky);
    }
}
